                { interval: "60,000 km", timeLimit: "5 years", task: "DL501 MTF Gear Fluid Change", details: "Change the gear oil portion of the transmission which lubricates the actual gear sets and front differential.", parts: ["4.5L MTF Gear Oil"], importance: "Medium", laborDifficulty: "Intermediate", estimatedCost: "100 - 150 EUR" }, 
                { interval: "80,000 km", timeLimit: "N/A", task: "Rear Differential Fluid", details: "Change hypoid gear oil on the rear axle.", parts: ["75W-90 GL-5"], importance: "Medium", laborDifficulty: "Intermediate", estimatedCost: "50 - 80 EUR" } 
