        engineeringData: { blockDesign: "All-Aluminum 90-degree V6 (EA837 architecture). Features Alusil cylinder liners rather than cast-iron, requiring specialized oil to prevent cylinder scoring.", crankshaft: "Forged Steel with 4 main bearings, featuring an offset 90-degree V-angle utilizing split-pin journals for even firing intervals.", pistonSpeed: "16.1 m/s @ 6500 RPM. A high-revving, naturally aspirated design that requires excellent lubrication.", alternator: "150A Bosch water-cooled variant on some specific high-spec models, or standard air-cooled depending on options.", rotatingAssembly: { pistonConstruction: "Cast Aluminum, designed for high 12.5:1 compression.", wristPinDiameter: "22 mm.", connectingRodLength: "153 mm.", rodBoltSize: "M9 x 1.0 stretch bolts.", crankMainJournal: "65.0 mm.", crankRodJournal: "56.0 mm.", rodRatio: "1.82, providing incredibly smooth operation and low cylinder wall side-loading." }, cylinderHead: { combustionChamberVol: "Optimized for extreme high compression FSI injection.", intakePortFlow: "24-valve DOHC design. Highly susceptible to carbon buildup.", valveSizes: "Intake: 33.0 mm / Exhaust: 28.0 mm.", valveStemDiameter: "6.0 mm.", camshaftDuration: "Continuous VVT on both intake and exhaust camshafts.", lifterType: "Hydraulic lifters paired with roller finger followers.", specialFeature: "Variable intake manifold with tumble flaps to increase low-RPM air velocity." }, oilAndCooling: { oilSquirters: "Yes, under-piston cooling jets.", oilPumpType: "Chain-driven variable displacement gear pump.", thermostatOpening: "87°C Mechanical.", oilCooler: "Water-to-oil heat exchanger." }, fuelSystem: { systemType: "Pure FSI Direct Injection.", maxPressure: "Up to 120 Bar.", injectors: "6x solenoid-type high-pressure injectors." }, tuningLimits: { maxSafeTorqueStock: "450 Nm.", maxSafePowerStock: "300 hp.", maxSafeRPM: "7000 RPM.", weakestLink: "Rear timing chain tensioners, massive carbon buildup, plastic intake manifold flaps." }, electrical: { coils: "Individual Coil-On-Plug (COP) system.", ecu: "Bosch MED 9.1." } },
