        tuningPotential: [ { stage: "Stage 1", power: "285 hp", notes: "Minimal peak horsepower gains due to naturally aspirated design. The tune focuses entirely on sharpening throttle response and removing factory limiters.", zeroToHundred: "6.7s", hundredToTwoHundred: "N/A" }, { stage: "Stage 2", power: "295 hp", notes: "Requires full exhaust system and high-flow cats. Not cost-effective for the minimal power gained.", zeroToHundred: "6.5s", hundredToTwoHundred: "N/A" }, { stage: "Stage 3", power: "N/A", notes: "No viable forced induction kits exist for the 3.2 FSI. If you want more power, buy the 3.0 TFSI.", zeroToHundred: "N/A", hundredToTwoHundred: "N/A" } ],
