        engineeringData: { blockDesign: "All-Aluminum 90-degree V6 (EA837 architecture). Features Alusil cylinder liners. An incredibly robust and over-engineered block designed to handle the immense low-end torque of the supercharger.", crankshaft: "Forged Steel with 4 main bearings, featuring an offset 90-degree V-angle utilizing split-pin journals for even firing intervals.", pistonSpeed: "16.1 m/s @ 6500 RPM. A robust rotating assembly built for forced induction.", alternator: "150A Bosch.", rotatingAssembly: { pistonConstruction: "Cast Aluminum, highly durable. Does not suffer from the catastrophic oil ring failures of the 2.0T.", wristPinDiameter: "22 mm.", connectingRodLength: "153 mm.", rodBoltSize: "M9 x 1.0 stretch bolts.", crankMainJournal: "65.0 mm.", crankRodJournal: "56.0 mm.", rodRatio: "1.82, providing incredibly smooth operation." }, cylinderHead: { combustionChamberVol: "Optimized for extreme forced induction FSI injection.", intakePortFlow: "24-valve DOHC design. Highly susceptible to carbon buildup as no fuel washes the ports.", valveSizes: "Intake: 33.0 mm / Exhaust: 28.0 mm.", valveStemDiameter: "6.0 mm.", camshaftDuration: "Continuous VVT on intake camshafts.", lifterType: "Hydraulic lifters paired with roller finger followers.", specialFeature: "The engine valley is entirely occupied by the massive Eaton TVS1320 roots-type supercharger." }, oilAndCooling: { oilSquirters: "Yes, under-piston cooling jets.", oilPumpType: "Chain-driven variable displacement gear pump.", thermostatOpening: "87°C Mechanical. Highly failure-prone, located under the supercharger.", oilCooler: "Water-to-oil heat exchanger." }, fuelSystem: { systemType: "Pure FSI Direct Injection.", maxPressure: "Up to 150 Bar.", injectors: "6x solenoid-type high-pressure injectors." }, tuningLimits: { maxSafeTorqueStock: "700 Nm (ZF8 limits).", maxSafePowerStock: "500+ hp.", maxSafeRPM: "7200 RPM.", weakestLink: "Catalytic converters melting under high boost, heat soak, and the PCV/thermostat under the blower." }, electrical: { coils: "Individual Coil-On-Plug (COP) system.", ecu: "Bosch SIMOS 8.5." } },
