        engineeringData: { blockDesign: "Cast Iron EA888 Gen 2. Closed-deck design with high rigidity. It lacks traditional starter motors and alternators, relying entirely on the high-voltage system.", crankshaft: "Forged Steel with 8 counterweights. Balanced with twin counter-rotating balance shafts.", pistonSpeed: "15.2 m/s @ 6000 RPM. A high-efficiency design marred by poorly engineered piston ring tolerances.", alternator: "None. Replaced by a high-voltage DC-DC converter and the transmission-mounted motor.", rotatingAssembly: { pistonConstruction: "Cast Aluminum, featuring thin low-friction rings that are the primary cause of oil consumption.", wristPinDiameter: "21 mm.", connectingRodLength: "144 mm.", rodBoltSize: "M8.5 x 1.0.", crankMainJournal: "58.0 mm.", crankRodJournal: "47.8 mm.", rodRatio: "1.67." }, cylinderHead: { combustionChamberVol: "Pent-roof with optimized FSI spray geometry.", intakePortFlow: "High-tumble, susceptible to heavy carbon choking.", valveSizes: "Intake: 33.8 mm / Exhaust: 28.0 mm.", valveStemDiameter: "6.0 mm.", camshaftDuration: "Continuous VVT on intake; Audi Valvelift (AVS) on exhaust.", lifterType: "Hydraulic with roller followers.", specialFeature: "Chain-driven balance shafts for NVH reduction." }, oilAndCooling: { oilSquirters: "Yes, under-piston cooling.", oilPumpType: "Variable displacement vane pump.", thermostatOpening: "95°C Mechanical.", oilCooler: "Water-to-oil heat exchanger." }, fuelSystem: { systemType: "Pure FSI Direct Injection.", maxPressure: "150 Bar.", injectors: "Solenoid-type high-pressure." }, tuningLimits: { maxSafeTorqueStock: "550 Nm (Transmission limited).", maxSafePowerStock: "350 hp (Post-rebuild ICE internals).", maxSafeRPM: "6800 RPM.", weakestLink: "Piston rings, timing tensioner, high-voltage battery, and electric A/C compressor." }, electrical: { coils: "COP system.", ecu: "Bosch MED 17.1.1." } },
