        tuningPotential: [ { stage: "Stage 1", power: "285 hp (Combined)", notes: "Software flash focuses on the ICE engine. Yields huge mid-range gains, but the hybrid clutch limits extreme torque tuning.", zeroToHundred: "6.8s", hundredToTwoHundred: "N/A" }, { stage: "Stage 2", power: "310 hp (Combined)", notes: "Requires high-flow downpipe. Risk of overwhelming the hybrid disconnect clutch is high.", zeroToHundred: "6.3s", hundredToTwoHundred: "N/A" }, { stage: "Stage 3", power: "380 hp (Combined)", notes: "K04 swap. Extremely rare on hybrids due to drivetrain limitations and ECU complexity.", zeroToHundred: "5.5s", hundredToTwoHundred: "N/A" } ],
