        tuningPotential: [ { stage: "Stage 1", power: "185 - 195 hp", notes: "An ECU software flash yields phenomenal gains. Unlocks significantly more mid-range torque, pushing the car to over 400 Nm. A DL501 TCU tune is highly recommended to manage the massive diesel torque smoothly.", zeroToHundred: "8.5s", hundredToTwoHundred: "N/A" }, { stage: "Stage 2", power: "205 - 215 hp", notes: "Requires DPF and EGR removal (where legally permitted), plus a high-flow downpipe. Produces exhaust smoke but significantly lowers EGTs.", zeroToHundred: "7.8s", hundredToTwoHundred: "N/A" }, { stage: "Stage 3 (Hybrid Turbo)", power: "230 - 250 hp", notes: "Requires a larger hybrid turbocharger (e.g., GTD1752VRK) and CP4 fuel pump upgrades. Transforms the Q5 into a very fast diesel, but heavily stresses the DL501 transmission.", zeroToHundred: "7.0s", hundredToTwoHundred: "N/A" } ],
