        sisterModels: [ { name: "Audi A4 (B8) 2.0 TDI", note: "Shares the exact same EA189 engine and longitudinal chassis architecture." }, { name: "Audi A5 (B8) 2.0 TDI", note: "Identical powertrain configuration." } ],
        tuningPotential: [ { stage: "Stage 1", power: "185 - 195 hp", notes: "Because the 136hp CAGB is mechanically identical to the 143hp and 170hp versions, an ECU software flash yields phenomenal gains. Unlocks significantly more mid-range torque, pushing the car to over 400 Nm.", zeroToHundred: "8.6s", hundredToTwoHundred: "N/A" }, { stage: "Stage 2", power: "205 - 215 hp", notes: "Requires DPF and EGR removal (where legally permitted), plus a high-flow downpipe. Produces exhaust smoke but significantly lowers EGTs.", zeroToHundred: "7.9s", hundredToTwoHundred: "N/A" }, { stage: "Stage 3 (Hybrid Turbo)", power: "230 - 250 hp", notes: "Requires a larger hybrid turbocharger (e.g., GTD1752VRK) and CP4 fuel pump upgrades. Transforms the Q5 into a very fast diesel, but heavily stresses the DL501 transmission.", zeroToHundred: "7.1s", hundredToTwoHundred: "N/A" } ],
