        engineeringData: { blockDesign: "Cast Iron EA189 architecture. Extremely heavy, incredibly rigid closed-deck block designed for maximum durability under immense diesel compression.", crankshaft: "Forged Steel, 5 main bearings, highly balanced to handle low-end torque pulses.", pistonSpeed: "14.2 m/s @ 4500 RPM. Conservative piston speed guarantees low cylinder wear.", alternator: "140A Bosch.", rotatingAssembly: { pistonConstruction: "Cast Aluminum alloy featuring an internal oil cooling gallery to manage heat from the VNT turbo.", wristPinDiameter: "26 mm, massive thickness to handle diesel compression.", connectingRodLength: "144 mm, fracture-split.", rodBoltSize: "M8.5 x 1.0.", crankMainJournal: "54.0 mm.", crankRodJournal: "47.8 mm.", rodRatio: "1.67." }, cylinderHead: { combustionChamberVol: "In-piston bowl design.", intakePortFlow: "16-valve DOHC. Features swirl flaps to induce turbulence at low RPMs.", valveSizes: "Intake: 26.6 mm / Exhaust: 24.5 mm.", valveStemDiameter: "5.5 mm.", camshaftDuration: "Fixed duration, belt-driven.", lifterType: "Hydraulic lifters with roller followers.", specialFeature: "Prone to the P2015 intake manifold flap error due to plastic stop wear." }, oilAndCooling: { oilSquirters: "Yes, under-piston cooling jets.", oilPumpType: "Chain-driven from balance shaft. The 77mm hex key driving the pump is the engine's fatal flaw.", thermostatOpening: "87°C Mechanical.", oilCooler: "Water-to-oil heat exchanger." }, fuelSystem: { systemType: "Bosch Common Rail Direct Injection.", maxPressure: "1800 Bar.", injectors: "Piezoelectric injectors." }, tuningLimits: { maxSafeTorqueStock: "450 Nm (Clutch/DSG limited).", maxSafePowerStock: "230 hp (Turbo/Injector limited).", maxSafeRPM: "5000 RPM.", weakestLink: "CP4 Fuel Pump, Hex oil pump shaft, DL501 mechatronics." }, electrical: { coils: "Compression ignition, 4x High-voltage glow plugs.", ecu: "Bosch EDC17." } },
