        engineeringData: { blockDesign: "Cast Iron inline-4 (EA288 architecture). A massive evolutionary step over the EA189, completely relocating the balance shafts and replacing the fatal hex-shaft oil pump with a robust wet-belt driven pump.", crankshaft: "Forged Steel, 5 main bearings, highly balanced to handle low-end torque pulses.", pistonSpeed: "14.2 m/s @ 4500 RPM. Conservative piston speed guarantees low cylinder wear.", alternator: "140A Bosch.", rotatingAssembly: { pistonConstruction: "Cast Aluminum alloy featuring an internal oil cooling gallery to manage heat from the VNT turbo.", wristPinDiameter: "26 mm, massive thickness to handle diesel compression.", connectingRodLength: "144 mm, fracture-split.", rodBoltSize: "M8.5 x 1.0.", crankMainJournal: "54.0 mm.", crankRodJournal: "47.8 mm.", rodRatio: "1.67." }, cylinderHead: { combustionChamberVol: "In-piston bowl design.", intakePortFlow: "16-valve DOHC. Features an incredibly complex thermal management system with micro-circuits in the cylinder head to drastically accelerate engine warm-up.", valveSizes: "Intake: 26.6 mm / Exhaust: 24.5 mm.", valveStemDiameter: "5.5 mm.", camshaftDuration: "Fixed duration, belt-driven.", lifterType: "Hydraulic lifters with roller followers.", specialFeature: "Integrates both high-pressure and low-pressure EGR systems to meet Euro 6." }, oilAndCooling: { oilSquirters: "Yes, under-piston cooling jets.", oilPumpType: "Wet-belt driven fully variable displacement vane pump. Cures the EA189 hex shaft disaster.", thermostatOpening: "Electronic map-controlled rotary slide thermal management module.", oilCooler: "Standard water-to-oil heat exchanger." }, fuelSystem: { systemType: "Bosch Common Rail Direct Injection with SCR/AdBlue aftertreatment.", maxPressure: "Up to 2000 Bar.", injectors: "Solenoid-type high-pressure injectors." }, tuningLimits: { maxSafeTorqueStock: "480 Nm (DL501 limited).", maxSafePowerStock: "240 hp (Turbo/DPF limited).", maxSafeRPM: "5000 RPM.", weakestLink: "AdBlue/SCR system, variable water pump, DL501 mechatronics." }, electrical: { coils: "Compression ignition, 4x High-voltage glow plugs.", ecu: "Bosch EDC17." } },
