                { interval: "150,000 km", timeLimit: "10 years", task: "Upper Timing Chain Tensioner Replacement", details: "If cold-start rattle persists, replace the upper hydraulic tensioners.", parts: ["Upper Tensioners"], importance: "High", laborDifficulty: "Advanced", estimatedCost: "600 - 800 EUR" }
