                { interval: "60,000 km", timeLimit: "5 years", task: "DL501 MTF Gear Fluid Change", details: "Change the gear oil portion of the transmission which lubricates the actual gear sets.", parts: ["4.5L MTF Gear Oil"], importance: "Medium", laborDifficulty: "Intermediate", estimatedCost: "100 - 150 EUR" }, 
                { interval: "2 Years", timeLimit: "2 years", task: "Brake Fluid Flush", details: "Prevent ABS pump internal corrosion.", parts: ["1.0L DOT 4 Fluid"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "80 EUR" },
                { interval: "80,000 km", timeLimit: "8 years", task: "Rear Differential Fluid", details: "Change hypoid gear oil on the rear axle.", parts: ["75W-90 GL-5"], importance: "Medium", laborDifficulty: "Intermediate", estimatedCost: "60 EUR" }
