    engineeringData: { blockDesign: "Cast Iron 90-degree V6 (EA897 architecture). Extremely heavy, incredibly rigid closed-deck block designed for maximum durability under immense diesel compression.", crankshaft: "Forged Steel, 4 main bearings, highly balanced to handle massive low-end torque pulses.", pistonSpeed: "15.0 m/s @ 4500 RPM. Conservative piston speed guarantees exceptionally low cylinder wear.", alternator: "180A Bosch.", rotatingAssembly: { pistonConstruction: "Cast Aluminum alloy featuring an internal oil cooling gallery to manage heat from the massive VNT turbo.", wristPinDiameter: "30 mm, massive thickness to handle diesel compression.", connectingRodLength: "152 mm, fracture-split.", rodBoltSize: "M9 x 1.0.", crankMainJournal: "65.0 mm.", crankRodJournal: "56.0 mm.", rodRatio: "1.66." }, cylinderHead: { combustionChamberVol: "In-piston bowl design.", intakePortFlow: "24-valve DOHC.", valveSizes: "Intake: 28.5 mm / Exhaust: 26.5 mm.", valveStemDiameter: "6.0 mm.", camshaftDuration: "Fixed duration, chain-driven.", lifterType: "Hydraulic lifters with roller followers.", specialFeature: "Redesigned cylinder heads compared to EA896, eliminating the failure-prone physical intake swirl flaps in favor of better port geometry." }, oilAndCooling: { oilSquirters: "Yes, under-piston cooling jets.", oilPumpType: "Chain-driven fully variable displacement vane pump.", thermostatOpening: "87°C Mechanical.", oilCooler: "Water-to-oil heat exchanger located deep in the V of the engine block. The sealing plate beneath it is the engine's primary weak point." }, fuelSystem: { systemType: "Bosch Common Rail Direct Injection with SCR/AdBlue aftertreatment.", maxPressure: "2000 Bar.", injectors: "Piezoelectric injectors." }, tuningLimits: { maxSafeTorqueStock: "650 Nm (DL501 clutch pack limited).", maxSafePowerStock: "350 hp (Turbo/Injector limited).", maxSafeRPM: "5000 RPM.", weakestLink: "CP4 Fuel Pump, Engine 'V' seals, DL501 mechatronics." }, electrical: { coils: "Compression ignition, 6x High-voltage glow plugs.", ecu: "Bosch EDC17." } },
