    tuningPotential: [ { stage: "Stage 1", power: "300 - 320 hp", notes: "Because the 211hp CTBB is simply a software-locked version of the 258hp model, an ECU software flash yields phenomenal, transformative gains. Unlocks massive mid-range torque, pushing the car to over 650 Nm.", zeroToHundred: "5.8s", hundredToTwoHundred: "N/A" }, { stage: "Stage 2", power: "330 - 350 hp", notes: "Requires DPF and EGR removal (where legally permitted), plus a high-flow downpipe. Produces exhaust smoke but significantly lowers EGTs.", zeroToHundred: "5.4s", hundredToTwoHundred: "N/A" }, { stage: "Stage 3 (Hybrid Turbo)", power: "380 - 430 hp", notes: "Requires a larger hybrid turbocharger (e.g., GTB2260VK converted to ball-bearing or larger billet wheel) and CP4 fuel pump upgrades. Transforms the Q5 into an absolute rocket.", zeroToHundred: "4.8s", hundredToTwoHundred: "N/A" } ],
