            { interval: "15,000 km", timeLimit: "1 year", task: "AdBlue / DEF Refill", details: "Refill the 23-liter DEF tank. Do not let it run dry.", parts: ["ISO 22241 DEF"], importance: "High", laborDifficulty: "Easy", estimatedCost: "30 EUR" }
