    sisterModels: [ { name: "Audi A6 (C7) 3.0 BiTDI Competition", note: "Shares the exact same monstrous BiTDI EA897 engine and ZF8 transmission." }, { name: "Audi A7 (C7) 3.0 BiTDI Competition", note: "Identical powertrain configuration." } ],
    tuningPotential: [ { stage: "Stage 1", power: "370 - 390 hp", notes: "An ECU software flash yields astonishing gains. Unlocks massive mid-range torque, pushing the car to over 750 Nm. The ZF8 transmission handles this effortlessly.", zeroToHundred: "4.8s", hundredToTwoHundred: "N/A" }, { stage: "Stage 2", power: "390 - 420 hp", notes: "Requires DPF and EGR removal (where legally permitted), plus a high-flow downpipe and upgraded intercooler. Produces exhaust smoke but drastically lowers EGTs.", zeroToHundred: "4.4s", hundredToTwoHundred: "N/A" }, { stage: "Stage 3 (Hybrid Turbos)", power: "460 - 520+ hp", notes: "Requires upgrading BOTH turbochargers and the CP4 fuel pump. Transforms the SQ5 Competition into a terrifyingly fast vehicle that will embarrass dedicated sports cars while still returning great fuel economy.", zeroToHundred: "3.8s", hundredToTwoHundred: "N/A" } ],
