            { interval: "30,000 km", timeLimit: "2 years", task: "Engine Air Filter Replacement", details: "The supercharger requires massive amounts of airflow. A clogged filter severely limits power.", parts: ["Air Filter Element"], importance: "High", laborDifficulty: "Easy", estimatedCost: "35 EUR" },
            { interval: "30,000 km", timeLimit: "1 year", task: "Cabin Air Filter Replacement", details: "Replace filter to keep HVAC blower motor clear of debris.", parts: ["Cabin Filter"], importance: "Low", laborDifficulty: "Easy", estimatedCost: "25 EUR" }
