    tuningPotential: [ { stage: "Stage 1", power: "420 - 440 hp", notes: "An ECU software flash yields astonishing gains. A Stage 1 flash instantly unleashes the supercharger, pushing the SQ5 well beyond 400 horsepower with zero hardware changes.", zeroToHundred: "4.8s", hundredToTwoHundred: "N/A" }, { stage: "Stage 2 (Single Pulley)", power: "460 - 480 hp", notes: "Requires installing a smaller supercharger pulley to increase blower RPM, paired with an upgraded heat exchanger to combat heat soak.", zeroToHundred: "4.3s", hundredToTwoHundred: "N/A" }, { stage: "Stage 3 (Dual Pulley + E85)", power: "520 - 550+ hp", notes: "The ultimate path. Upgrading both the supercharger and crank pulleys, adding an E85 tune, and gutting the catalytic converters. Turns the SQ5 into a terrifyingly fast vehicle that will embarrass dedicated sports cars.", zeroToHundred: "3.7s", hundredToTwoHundred: "N/A" } ],
