    tuningPotential: [ { stage: "Stage 1", power: "190 - 200 hp", notes: "Because the 136hp DEUB is artificially restricted from the factory, an ECU software flash yields phenomenal, transformative gains. Unlocks significantly more mid-range torque, pushing the car to over 420 Nm.", zeroToHundred: "8.3s", hundredToTwoHundred: "N/A" }, { stage: "Stage 2", power: "210 - 220 hp", notes: "Requires DPF, EGR, and SCR removal (where legally permitted), plus a high-flow downpipe. Produces exhaust smoke but significantly lowers EGTs.", zeroToHundred: "7.7s", hundredToTwoHundred: "N/A" }, { stage: "Stage 3 (Hybrid Turbo)", power: "230 - 250 hp", notes: "Requires a larger hybrid turbocharger and HPFP upgrades. Transforms the Q5 into a very fast diesel, but pushes the DL382 transmission to its limits.", zeroToHundred: "6.9s", hundredToTwoHundred: "N/A" } ],
