    engineeringData: { blockDesign: "Cast Iron inline-4 (EA288 Evo architecture). A highly refined evolutionary step featuring a massive reduction in internal friction, separate cooling circuits for the block and head, and acoustic enhancements to mask diesel clatter.", crankshaft: "Forged Steel, 5 main bearings, highly balanced to handle low-end torque pulses.", pistonSpeed: "14.2 m/s @ 4500 RPM. Conservative piston speed guarantees exceptionally low cylinder wear.", alternator: "12V Belt Alternator Starter (BAS) system integrated into the MHEV network.", rotatingAssembly: { pistonConstruction: "Cast Aluminum alloy featuring an internal oil cooling gallery and optimized low-friction rings.", wristPinDiameter: "26 mm, massive thickness to handle diesel compression.", connectingRodLength: "144 mm, fracture-split.", rodBoltSize: "M8.5 x 1.0.", crankMainJournal: "54.0 mm.", crankRodJournal: "47.8 mm.", rodRatio: "1.67." }, cylinderHead: { combustionChamberVol: "In-piston bowl design.", intakePortFlow: "16-valve DOHC. Features an incredibly complex thermal management system with micro-circuits in the cylinder head to drastically accelerate engine warm-up.", valveSizes: "Intake: 26.6 mm / Exhaust: 24.5 mm.", valveStemDiameter: "5.5 mm.", camshaftDuration: "Fixed duration, belt-driven.", lifterType: "Hydraulic lifters with roller followers.", specialFeature: "Integrates Twin-Dosing dual high-pressure and low-pressure EGR systems." }, oilAndCooling: { oilSquirters: "Yes, under-piston cooling jets.", oilPumpType: "Wet-belt driven fully variable displacement vane pump.", thermostatOpening: "Electronic map-controlled rotary slide thermal management module.", oilCooler: "Standard water-to-oil heat exchanger." }, fuelSystem: { systemType: "Bosch Common Rail Direct Injection with Twin-Dosing SCR/AdBlue aftertreatment.", maxPressure: "Up to 2200 Bar.", injectors: "Solenoid-type high-pressure injectors." }, tuningLimits: { maxSafeTorqueStock: "500 Nm (DL382 transmission limits).", maxSafePowerStock: "250 hp (Turbo/DPF limited).", maxSafeRPM: "5000 RPM.", weakestLink: "AdBlue/SCR system, variable water pump, DL382 clutch packs." }, electrical: { coils: "Compression ignition, 4x High-voltage glow plugs.", ecu: "Bosch MD1CS004." } },
