    engineeringData: { blockDesign: "Cast Iron 90-degree V6 (EA897 Evo2 architecture). Extremely heavy, incredibly rigid closed-deck block designed specifically to handle immense cylinder pressures.", crankshaft: "Forged Steel, 4 main bearings, highly balanced to handle massive low-end torque pulses.", pistonSpeed: "15.0 m/s @ 4500 RPM. Conservative piston speed guarantees exceptionally low cylinder wear.", alternator: "48V Belt Alternator Starter (BAS) system integrated into the MHEV network.", rotatingAssembly: { pistonConstruction: "Cast Aluminum alloy featuring an internal oil cooling gallery and specialized ceramic coatings on the piston crowns for extreme heat resistance.", wristPinDiameter: "30 mm, massive thickness to handle diesel compression.", connectingRodLength: "152 mm, fracture-split.", rodBoltSize: "M9 x 1.0.", crankMainJournal: "65.0 mm.", crankRodJournal: "56.0 mm.", rodRatio: "1.66." }, cylinderHead: { combustionChamberVol: "In-piston bowl design.", intakePortFlow: "24-valve DOHC.", valveSizes: "Intake: 28.5 mm / Exhaust: 26.5 mm.", valveStemDiameter: "6.0 mm.", camshaftDuration: "Fixed duration, chain-driven.", lifterType: "Hydraulic lifters with roller followers.", specialFeature: "Features an intricate thermal management system to heat the engine block faster for Euro 6d emissions." }, oilAndCooling: { oilSquirters: "Yes, under-piston cooling jets for extreme heat management.", oilPumpType: "Chain-driven fully variable displacement vane pump.", thermostatOpening: "Electronic map-controlled thermal management module.", oilCooler: "Massive water-to-oil heat exchanger located deep in the V of the engine block. The sealing plate beneath it is the engine's primary weak point." }, fuelSystem: { systemType: "Bosch Common Rail Direct Injection with SCR/AdBlue aftertreatment.", maxPressure: "2000 Bar.", injectors: "Piezoelectric injectors." }, tuningLimits: { maxSafeTorqueStock: "750 Nm (ZF8 transmission limits).", maxSafePowerStock: "380 hp (Turbo/Injector limited).", maxSafeRPM: "5000 RPM.", weakestLink: "CP4 Fuel Pump, Engine 'V' seals, AdBlue/SCR system." }, electrical: { coils: "Compression ignition, 6x High-voltage glow plugs.", ecu: "Bosch MD1." } },
