    engineeringData: { blockDesign: "Cast Iron EA888 Gen 3B architecture. Closed-deck block optimized for the 'Budack Cycle' (B-Cycle), featuring early intake valve closure for extreme thermal efficiency and diesel-like low-end torque.", crankshaft: "Forged Steel, 5 main bearings, highly balanced with twin counter-rotating balance shafts.", pistonSpeed: "15.2 m/s @ 6000 RPM. Features completely redesigned 3-piece oil control rings that perfectly cure the older Gen 2 oil consumption disaster.", alternator: "140A Bosch.", rotatingAssembly: { pistonConstruction: "Cast Aluminum alloy, featuring an ultra-high 11.7:1 compression ratio specific to the B-Cycle efficiency engine.", wristPinDiameter: "21 mm.", connectingRodLength: "144 mm, fracture-split.", rodBoltSize: "M8.5 x 1.0.", crankMainJournal: "58.0 mm.", crankRodJournal: "47.8 mm.", rodRatio: "1.67." }, cylinderHead: { combustionChamberVol: "Pent-roof optimized for dual injection (FSI + MPI).", intakePortFlow: "16-valve DOHC. Integrated exhaust manifold surrounded by a water jacket for rapid warm-up and extreme thermal control.", valveSizes: "Intake: 33.8 mm / Exhaust: 28.0 mm.", valveStemDiameter: "6.0 mm.", camshaftDuration: "Continuous VVT. Features Audi Valvelift System (AVS) on the intake side for B-Cycle operation.", lifterType: "Hydraulic lifters with roller followers.", specialFeature: "Dual injection system keeps intake valves clean, mostly eliminating the need for walnut blasting." }, oilAndCooling: { oilSquirters: "Yes, under-piston cooling jets.", oilPumpType: "Chain-driven, fully variable displacement vane pump.", thermostatOpening: "105°C Electronic rotary map-controlled module.", oilCooler: "Standard water-to-oil heat exchanger." }, fuelSystem: { systemType: "Dual FSI Direct Injection + MPI Port Injection.", maxPressure: "250 Bar (FSI).", injectors: "8x total (4 High-pressure solenoid, 4 Low-pressure port)." }, tuningLimits: { maxSafeTorqueStock: "500 Nm (DL382 limited).", maxSafePowerStock: "350 hp (Requires IS38 swap. Tuning must heavily account for the 11.7:1 compression ratio to avoid knock).", maxSafeRPM: "6800 RPM.", weakestLink: "Plastic water pump module, PCV valve, high compression limit for boost." }, electrical: { coils: "Individual Coil-On-Plug (COP) system.", ecu: "Bosch SIMOS 18." } },
