    tuningPotential: [ { stage: "Stage 1", power: "310 - 320 hp", notes: "An ECU software flash yields phenomenal, transformative gains. Pushes the car to over 480 Nm. Completely changes the character of the SUV.", zeroToHundred: "5.9s", hundredToTwoHundred: "N/A" }, { stage: "Stage 2", power: "330 - 345 hp", notes: "Requires a high-flow downpipe and intercooler. Unlocks incredible top-end pull.", zeroToHundred: "5.4s", hundredToTwoHundred: "N/A" }, { stage: "Stage 3 (IS38 Turbo Swap)", power: "380 - 410 hp", notes: "Swapping the factory turbo for the larger IS38 from the S3/Golf R. The standard 9.6:1 compression block handles this beautifully. Transforms the Q5 into an absolute rocket.", zeroToHundred: "4.8s", hundredToTwoHundred: "N/A" } ],
