    tuningPotential: [ { stage: "Stage 1", power: "300 - 315 hp", notes: "An ECU software flash yields phenomenal, transformative gains. Pushes the car to over 460 Nm. Completely changes the character of the SUV.", zeroToHundred: "6.0s", hundredToTwoHundred: "N/A" }, { stage: "Stage 2", power: "320 - 335 hp", notes: "Requires a high-flow downpipe and intercooler. The OPF significantly limits Stage 2 potential unless removed (where legally permitted).", zeroToHundred: "5.5s", hundredToTwoHundred: "N/A" }, { stage: "Stage 3 (IS38 Turbo Swap)", power: "370 - 390 hp", notes: "Swapping the factory turbo for the larger IS38 from the S3/Golf R. The standard 9.6:1 compression block handles this beautifully.", zeroToHundred: "4.9s", hundredToTwoHundred: "N/A" } ],
