    engineeringData: { blockDesign: "Cast Iron EA888 Gen 4 architecture. Closed-deck block optimized for extreme performance and strict emissions compliance.", crankshaft: "Forged Steel, 5 main bearings, highly balanced with twin counter-rotating balance shafts.", pistonSpeed: "15.2 m/s @ 6000 RPM. Features completely redesigned 3-piece oil control rings that perfectly cure the older Gen 2 oil consumption disaster.", alternator: "12V Belt Alternator Starter (BAS) system integrated into the MHEV network.", rotatingAssembly: { pistonConstruction: "Cast Aluminum alloy, featuring a strong 9.6:1 compression ratio ideal for turbocharging.", wristPinDiameter: "21 mm.", connectingRodLength: "144 mm, fracture-split.", rodBoltSize: "M8.5 x 1.0.", crankMainJournal: "58.0 mm.", crankRodJournal: "47.8 mm.", rodRatio: "1.67." }, cylinderHead: { combustionChamberVol: "Pent-roof optimized for direct injection.", intakePortFlow: "16-valve DOHC. Integrated exhaust manifold surrounded by a water jacket for rapid warm-up and extreme thermal control.", valveSizes: "Intake: 33.8 mm / Exhaust: 28.0 mm.", valveStemDiameter: "6.0 mm.", camshaftDuration: "Continuous VVT. Features Audi Valvelift System (AVS) on the exhaust side for rapid turbo spool.", lifterType: "Hydraulic lifters with roller followers.", specialFeature: "Massively improved PCV and thermal management systems." }, oilAndCooling: { oilSquirters: "Yes, under-piston cooling jets.", oilPumpType: "Chain-driven, fully variable displacement vane pump.", thermostatOpening: "105°C Electronic rotary map-controlled module.", oilCooler: "Standard water-to-oil heat exchanger." }, fuelSystem: { systemType: "Direct Injection (FSI) operating at extremely high pressure.", maxPressure: "350 Bar.", injectors: "4 High-pressure solenoid injectors." }, tuningLimits: { maxSafeTorqueStock: "500 Nm (DL382 limited).", maxSafePowerStock: "400 hp (With larger turbo upgrade).", maxSafeRPM: "6800 RPM.", weakestLink: "Plastic water pump module, PCV valve, DL382 clutch packs, OPF restriction." }, electrical: { coils: "Individual Coil-On-Plug (COP) system.", ecu: "Bosch SIMOS 19." } },
