    tuningPotential: [ { stage: "Stage 1", power: "310 - 320 hp", notes: "An ECU software flash yields phenomenal, transformative gains. Pushes the car to over 480 Nm. Completely changes the character of the SUV.", zeroToHundred: "5.8s", hundredToTwoHundred: "N/A" }, { stage: "Stage 2", power: "330 - 345 hp", notes: "Requires a high-flow downpipe and intercooler. The OPF significantly limits Stage 2 potential unless removed (where legally permitted).", zeroToHundred: "5.3s", hundredToTwoHundred: "N/A" }, { stage: "Stage 3 (Turbo Swap)", power: "380 - 410 hp", notes: "Swapping the factory turbo for a larger unit. The standard 9.6:1 compression block handles this beautifully.", zeroToHundred: "4.7s", hundredToTwoHundred: "N/A" } ],
