    tuningPotential: [ { stage: "Stage 1", power: "400 - 420 hp (Combined)", notes: "An ECU software flash targets the combustion engine. It yields excellent gains, pushing the ICE power up significantly, resulting in a brutal combined output when the battery is charged.", zeroToHundred: "4.9s", hundredToTwoHundred: "N/A" }, { stage: "Stage 2", power: "420 - 440 hp (Combined)", notes: "Requires a high-flow downpipe and intercooler. Pushes the DL382e transmission and electric motor clutch to their absolute limits.", zeroToHundred: "4.6s", hundredToTwoHundred: "N/A" }, { stage: "Stage 3", power: "N/A", notes: "Turbo swaps are generally avoided on the PHEV models due to the extreme complexity of the hybrid mapping and the mechanical limits of the disconnect clutch.", zeroToHundred: "N/A", hundredToTwoHundred: "N/A" } ],
