    engineeringData: { blockDesign: "All-Aluminum 90-degree V6 (EA839 architecture). Features cast-in steel cylinder liners. Uses the 'B-Cycle' (Budack Cycle) for extreme thermal efficiency at low loads.", crankshaft: "Forged Steel, 4 main bearings, highly balanced to handle the immense torque of the Hot-V turbo.", pistonSpeed: "15.0 m/s @ 6500 RPM. Features strong, short-skirt pistons.", alternator: "150A Bosch.", rotatingAssembly: { pistonConstruction: "Cast Aluminum alloy, featuring an 11.2:1 compression ratio.", wristPinDiameter: "22 mm.", connectingRodLength: "153 mm.", rodBoltSize: "M9 x 1.0.", crankMainJournal: "65.0 mm.", crankRodJournal: "56.0 mm.", rodRatio: "1.72." }, cylinderHead: { combustionChamberVol: "Pent-roof optimized for FSI and the B-Cycle.", intakePortFlow: "24-valve DOHC.", valveSizes: "Intake: 33.0 mm / Exhaust: 28.0 mm.", valveStemDiameter: "6.0 mm.", camshaftDuration: "Continuous VVT. Features Audi Valvelift System (AVS) on the intake side.", lifterType: "Hydraulic lifters with roller followers. (EARLY 2017-2018 ROLLER FOLLOWERS ARE CRITICALLY FLAWED).", specialFeature: "Integrated exhaust manifold exiting into the engine 'V' directly into the twin-scroll turbocharger." }, oilAndCooling: { oilSquirters: "Yes, under-piston cooling jets.", oilPumpType: "Chain-driven variable displacement gear pump.", thermostatOpening: "Electronic map-controlled rotary slide thermal management module.", oilCooler: "Water-to-oil heat exchanger." }, fuelSystem: { systemType: "Pure FSI Direct Injection.", maxPressure: "250 Bar.", injectors: "6x solenoid-type high-pressure injectors." }, tuningLimits: { maxSafeTorqueStock: "750 Nm (ZF8 limits).", maxSafePowerStock: "550+ hp.", maxSafeRPM: "6800 RPM.", weakestLink: "Early rocker arms (2017-2018), PCV valve, heat soak due to Hot-V layout." }, electrical: { coils: "Individual Coil-On-Plug (COP) system.", ecu: "Bosch MG1." } },
