    engineeringData: { blockDesign: "Cast Iron EA888 Gen 4 architecture. Closed-deck block optimized for high performance and boost pressure. The definitive 2.0L turbo platform of its generation.", crankshaft: "Forged Steel, 5 main bearings, highly balanced with twin counter-rotating balance shafts.", pistonSpeed: "15.2 m/s @ 6000 RPM. Features incredibly precise 3-piece oil control rings.", alternator: "Replaced by a 48V Powertrain Generator (PTG) integrated directly into the DL382+ transmission housing.", rotatingAssembly: { pistonConstruction: "Cast Aluminum alloy, featuring a strong 9.6:1 compression ratio ideal for turbocharging.", wristPinDiameter: "21 mm.", connectingRodLength: "144 mm, fracture-split.", rodBoltSize: "M8.5 x 1.0.", crankMainJournal: "58.0 mm.", crankRodJournal: "47.8 mm.", rodRatio: "1.67." }, cylinderHead: { combustionChamberVol: "Pent-roof optimized for FSI.", intakePortFlow: "16-valve DOHC. Integrated exhaust manifold surrounded by a water jacket.", valveSizes: "Intake: 33.8 mm / Exhaust: 28.0 mm.", valveStemDiameter: "6.0 mm.", camshaftDuration: "Continuous VVT. Features Audi Valvelift System (AVS) on the exhaust side for rapid turbo spool.", lifterType: "Hydraulic lifters with roller followers.", specialFeature: "Operates closely with the 48V PTG motor to allow pure electric maneuvering at very low speeds." }, oilAndCooling: { oilSquirters: "Yes, under-piston cooling jets.", oilPumpType: "Chain-driven, fully variable displacement vane pump.", thermostatOpening: "105°C Electronic rotary map-controlled module.", oilCooler: "Standard water-to-oil heat exchanger." }, fuelSystem: { systemType: "Direct Injection (FSI) at ultra-high pressure.", maxPressure: "350 Bar (FSI).", injectors: "4 High-pressure solenoid injectors." }, tuningLimits: { maxSafeTorqueStock: "500 Nm (DL382+ limited).", maxSafePowerStock: "400 hp (Requires larger turbo swap).", maxSafeRPM: "6800 RPM.", weakestLink: "Plastic water pump module, PCV valve, 48V battery thermal limits." }, electrical: { coils: "Individual Coil-On-Plug (COP) system.", ecu: "Bosch SIMOS 19 with integrated MHEV controller." } },
