    engineeringData: { blockDesign: "Cast Iron EA888 Gen 4 architecture. Closed-deck block optimized for extreme performance. The ICE component is highly robust, but faces severe thermal shock from frequent cold-load starts when the battery depletes.", crankshaft: "Forged Steel, 5 main bearings, highly balanced with twin counter-rotating balance shafts.", pistonSpeed: "15.2 m/s @ 6000 RPM. Features completely redesigned 3-piece oil control rings that perfectly cure the older Gen 2 oil consumption disaster.", alternator: "None. Traditional alternator is replaced by the High-Voltage electric motor in the transmission and a DC-DC converter.", rotatingAssembly: { pistonConstruction: "Cast Aluminum alloy, featuring a strong 9.6:1 compression ratio.", wristPinDiameter: "21 mm.", connectingRodLength: "144 mm, fracture-split.", rodBoltSize: "M8.5 x 1.0.", crankMainJournal: "58.0 mm.", crankRodJournal: "47.8 mm.", rodRatio: "1.67." }, cylinderHead: { combustionChamberVol: "Pent-roof optimized for FSI.", intakePortFlow: "16-valve DOHC. Integrated exhaust manifold surrounded by a water jacket for rapid warm-up.", valveSizes: "Intake: 33.8 mm / Exhaust: 28.0 mm.", valveStemDiameter: "6.0 mm.", camshaftDuration: "Continuous VVT.", lifterType: "Hydraulic lifters with roller followers.", specialFeature: "Integrated exhaust manifold significantly improves thermal management." }, oilAndCooling: { oilSquirters: "Yes, under-piston cooling jets.", oilPumpType: "Chain-driven, fully variable displacement vane pump.", thermostatOpening: "105°C Electronic rotary map-controlled module.", oilCooler: "Standard water-to-oil heat exchanger." }, fuelSystem: { systemType: "FSI Direct Injection.", maxPressure: "350 Bar (FSI).", injectors: "4 High-pressure solenoid injectors." }, tuningLimits: { maxSafeTorqueStock: "500 Nm (DL382e clutch limits).", maxSafePowerStock: "400 hp (Combined. Tuning the ICE is common, but the electric motor output remains fixed).", maxSafeRPM: "6800 RPM.", weakestLink: "High-Voltage battery cooling heater, electric motor clutch, plastic ICE water pump module." }, electrical: { coils: "Individual Coil-On-Plug (COP) system.", ecu: "Bosch SIMOS 19 paired with complex Hybrid Powertrain Control Module." } },
